// Generated by tools/gen_violation_matrix.py; change the generator, not this file.
// The standard leaves the order of reports to the tool (12.4.2.1); kirimasim
// confirms them in the order of the processes, which is the order of the source
// here (SCHEDULER_SPEC.md 15.4). The initial procedure wakes them last first.
`timescale 1ns/1ns
module top;
  logic [1:0] sel, a, b;
  int hits;
  logic g0, g1, g2, g3, g4, g5;
  always @(g0) begin
    unique case (sel)
      a: hits++;
      b: hits++;
    endcase
  end
  always @(g1) begin
    unique0 case (sel)
      a: hits++;
      b: hits++;
    endcase
  end
  always @(g2) begin
    priority case (sel)
      ~a: hits++;
      ~b: hits++;
    endcase
  end
  always @(g3) begin
    unique if (sel == a) hits++;
    else if (sel == b) hits++;
  end
  always @(g4) begin
    unique0 if (sel == a) hits++;
    else if (sel == b) hits++;
  end
  always @(g5) begin
    priority if (sel != a) hits++;
    else if (sel != b) hits++;
  end
  initial begin
    sel = 2'd1;
    a = 2'd1;
    b = 2'd1;
    #1;
    g5 = 1'b1;
    g4 = 1'b1;
    g3 = 1'b1;
    g2 = 1'b1;
    g1 = 1'b1;
    g0 = 1'b1;
    #1 $display("hits %0d", hits);
  end
endmodule
